    func testPortraitLayoutKeepsAspectAndHudAboveWorld() {
        let l = Layout(viewW: 1080, viewH: 2400, worldW: 1080, worldH: 1920)
        XCTAssertEqual((2400 - l.hudHeight - l.world.h) / 2, l.world.y - l.hudHeight, accuracy: eps)
        XCTAssertGreaterThanOrEqual(l.world.y, l.hudHeight - eps)   // the world never overlaps the HUD bar
        XCTAssertEqual(l.world.w / l.world.h, 1080.0 / 1920.0, accuracy: 0.0001)
        assertInside(Box(0, 0, 1080, 2400), l.world)
        XCTAssertEqual(l.scale, 1, accuracy: 0.0001)
    }

    func testLandscapeLayoutFitsHeightBesideTheHudBar() {
        let l = Layout(viewW: 2400, viewH: 1080, worldW: 1920, worldH: 1080)
        XCTAssertGreaterThanOrEqual(l.hudHeight, Layout.hudMin)
        XCTAssertGreaterThanOrEqual(l.world.y, l.hudHeight - eps)
        XCTAssertEqual(l.world.w / l.world.h, 1920.0 / 1080.0, accuracy: 0.0001)
        assertInside(Box(0, 0, 2400, 1080), l.world)
        XCTAssertEqual((2400 - l.world.w) / 2, l.world.x, accuracy: eps)
    }

    func testTheTopInsetPushesHudAndWorldDown() {
        let plain = Layout(viewW: 1080, viewH: 2400, worldW: 1080, worldH: 1920)
        let inset = Layout(viewW: 1080, viewH: 2400, worldW: 1080, worldH: 1920, insetTop: 100)
        XCTAssertEqual(inset.hud.y, 100)                              // the HUD bar starts below the inset
        XCTAssertGreaterThanOrEqual(inset.world.y, 100 + inset.hudHeight - eps)   // and the world below the HUD bar
        XCTAssertLessThanOrEqual(inset.scale, plain.scale + eps)
        assertInside(Box(0, 0, 1080, 2400), inset.world)
    }

    func testTheBottomInsetKeepsTheWorldClearOfTheGestureBar() {
        let l = Layout(viewW: 1080, viewH: 2400, worldW: 1080, worldH: 1920, insetTop: 100, insetBottom: 120)
        XCTAssertLessThanOrEqual(l.world.bottom, 2400 - 120 + eps)   // the world ends above the bar
        XCTAssertGreaterThanOrEqual(l.world.y, 100 + l.hudHeight - eps)
