        let land = Layout(viewW: 2400, viewH: 1080, worldW: 1920, worldH: 1080, insetBottom: 60)
        XCTAssertLessThanOrEqual(land.world.bottom, 1080 - 60 + eps)
        XCTAssertGreaterThan(Layout(viewW: 2400, viewH: 1080, worldW: 1920, worldH: 1080).scale, land.scale)
