    func testDegenerateViewsDoNotDivideByZero() {
        XCTAssertEqual(Layout(viewW: 0, viewH: 0, worldW: 1080, worldH: 1920).scale, 0)
        XCTAssertEqual(Layout(viewW: 100, viewH: 100, worldW: 0, worldH: 10).scale, 0)
        let tiny = Layout(viewW: 50, viewH: 20, worldW: 100, worldH: 100)
        XCTAssertLessThanOrEqual(tiny.hudHeight, 20 * Layout.hudMaxFraction + eps)
        XCTAssertGreaterThan(tiny.scale, 0)
    }

    func testEntitiesAreClippedToTheWorldRectangle() {
        let l = Layout(viewW: 1000, viewH: 1000, worldW: 100, worldH: 100)
        let full = l.toScreen(Box(10, 10, 20, 20))
        let inside = l.visible(Box(10, 10, 20, 20))
        XCTAssertNotNil(inside)
        XCTAssertEqual(full.x, inside?.x ?? -1, accuracy: eps)
        XCTAssertEqual(full.w, inside?.w ?? -1, accuracy: eps)
        XCTAssertEqual(full.h, inside?.h ?? -1, accuracy: eps)
        let right = l.visible(Box(90, 10, 30, 20))
        XCTAssertEqual(right?.right ?? -1, l.world.right, accuracy: eps)
        XCTAssertEqual(right?.w ?? -1, 10 * l.scale, accuracy: eps)
        let below = l.visible(Box(10, 95, 20, 20))
        XCTAssertEqual(below?.bottom ?? -1, l.world.bottom, accuracy: eps)
        XCTAssertNil(l.visible(Box(-30, 10, 20, 20)))   // completely outside
        XCTAssertNil(l.visible(Box(100, 10, 20, 20)))   // only touching the edge
    }

