    func testBurstSpawnsWhenAnEffectEntityVanishesInsideTheWorld() {
        var t = EffectTracker(effects: [.none, .burst, .pickup], world: world)
        t.observe(score: 0, lives: 3, entities: [at(1, 1, 400, 400)])
        XCTAssertTrue(t.particles.isEmpty)
        t.observe(score: 10, lives: 3, entities: [])
        XCTAssertEqual(t.particles.count, 8)
        XCTAssertEqual(t.particles[0].x, 450, accuracy: eps)
        XCTAssertEqual(t.particles[0].kind, 1)
        XCTAssertEqual(t.popups.first?.text, "+10")
        t.advance(0.2)
        XCTAssertGreaterThan(t.particles[0].x, 450)
        XCTAssertEqual(t.particles[0].alpha, 0.5, accuracy: 0.1)
        t.advance(0.3)
        XCTAssertTrue(t.particles.isEmpty)
    }

    func testPickupSpawnsARingAndNoParticles() {
        var t = EffectTracker(effects: [.pickup], world: world)
        t.observe(score: 0, lives: 3, entities: [at(1, 0, 400, 400)])
        t.observe(score: 5, lives: 3, entities: [])
        XCTAssertEqual(t.rings.count, 1)
        XCTAssertTrue(t.particles.isEmpty)
        t.advance(0.15)
        XCTAssertEqual(t.rings[0].radius, 50, accuracy: eps)
        t.advance(0.2)
        XCTAssertTrue(t.rings.isEmpty)
