    func testLosingALifeFlashesAndShakesThenSettles() {
        var t = EffectTracker(effects: [.none], world: world)
        t.observe(score: 0, lives: 3, entities: [])
        XCTAssertEqual(t.flash, 0)
        XCTAssertEqual(t.shakeX, 0)
        t.observe(score: 0, lives: 2, entities: [])
        XCTAssertEqual(t.flash, 1)
        XCTAssertGreaterThan(abs(t.shakeX), 0)
        XCTAssertEqual(t.shakeY, t.shakeX * -0.5)
