    func testGainingALifeOrResettingDoesNotFlash() {
        var t = EffectTracker(effects: [.burst], world: world)
        t.observe(score: 0, lives: 2, entities: [at(1, 0, 400, 400)])
        t.observe(score: 0, lives: 3, entities: [])
